import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './text.module.css'

export interface TextProps extends HTMLAttributes<HTMLElement> {
  /**
   * `p` for a paragraph, `span` for inline text, `div` for a block that imposes no semantics
   * of its own.
   *
   * @defaultValue `p`
   * @see the component manifest
   */
  as?: 'p' | 'span' | 'div'
  size?: 'sm' | 'md' | 'lg'
  weight?: 'normal' | 'medium' | 'semibold'
  /**
   * When true, renders in a muted/subtle color. `Text` has no `tone` prop: `tone` is the
   * severity vocabulary (Status, Badge, Timeline, SideNav); text emphasis is `muted`.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  muted?: boolean
}

export function Text({
  as: Component = 'p',
  size = 'md',
  weight = 'normal',
  muted = false,
  className,
  children,
  ...props
}: TextProps) {
  return (
    <Component
      data-size={size}
      data-weight={weight}
      data-muted={muted ? '' : undefined}
      className={cn(styles['text'], className as string | undefined)}
      {...(props as Record<string, unknown>)}
    >
      {children}
    </Component>
  )
}

@layer cascivo.component {
  .text {
    margin: 0;
    font-family: var(--cascivo-font-sans);
    line-height: var(--cascivo-leading-normal);
    color: var(--cascivo-color-text);

    /* Same trim, same `text text` edges as `Heading` — see the note there for why it is
       scoped to these two primitives and why the textbook `cap`/`ex` pairings are the wrong
       choice against a space scale that was tuned against untrimmed boxes. Body copy at
       `leading-normal` (1.5) carries the most half-leading of anything in the catalog, so
       it is where this is most worth having. */
    @supports (text-box-trim: trim-both) {
      text-box-trim: trim-both;
      text-box-edge: text text;
    }

    &[data-size='sm'] {
      font-size: var(--cascivo-text-sm);
    }

    &[data-size='md'] {
      font-size: var(--cascivo-text-base);
    }

    &[data-size='lg'] {
      font-size: var(--cascivo-text-lg);
    }

    &[data-weight='normal'] {
      font-weight: var(--cascivo-font-normal);
    }

    &[data-weight='medium'] {
      font-weight: var(--cascivo-font-medium);
    }

    &[data-weight='semibold'] {
      font-weight: var(--cascivo-font-semibold);
    }

    &[data-muted] {
      color: var(--cascivo-color-text-subtle);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

